use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = "You are a customer support agent. Answer the user's \
                      question using the supplied knowledge. If you need more \
                      information from the knowledge base, request the `lookup` \
                      tool with a focused query.";

        // Build the initial prompt from the attenuated context. The question is
        // the only free-text residual and is bounded by the node's `requires`.
        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');
        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);

        // Bounded tool-orchestration loop. The only tool in scope is `lookup`,
        // backed by the read-only knowledge-base handle.
        const MAX_ROUNDS: usize = 4;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // The model asked for a tool this node does not hold.
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "requested tool `{}` is not in this node's scope",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the \
                      permitted number of rounds"
                .to_string(),
        })
    }
}

export!(Node);
```

